// Returns a normal deviate (mu=0, sigma=1).
function randn() {
  let u, v, x, y, q;
  do {
    u = Math.random();
    v = 1.7156 * (Math.random() - 0.5);
    x = u - 0.449871;
    y = Math.abs(v) + 0.386595;
    q = x * x + y * (0.19600 * y - 0.25472 * x);
  } while (q &gt; 0.27597 && (q &gt; 0.27846 || v * v &gt; -4 * Math.log(u) * u * u));
  return v / u;
}







