function sample_finite_pop(data, n, nRep){
  // Sample nRep samples of size n from the data and return the mean in each sample
  var samplemeans = [];
  for (let i = 0; i &lt; nRep; ++i) {
    samplemeans.push({sample: i+1, mean: d3.mean(ss.sample(data, n).map(d =&gt; d.x))})
  }
  return samplemeans;
}







